engine.initial:
const main = engine.createDisplay({ name: 'main', width: 400, height: 300, transparent: false });
main.addObjectById('player');
main.EnemyCoolDown = 0;

engine.frame:
main.EnemyCoolDown -= dt;
if(main.EnemyCoolDown <= 0){
    main.EnemyCoolDown = Math.random() * 0.5 + 0.2;
    main.addObjectById('enemy', { y:Math.floor(Math.random() * 300) })
}

