// --- 移動・攻撃 ---
if (INPUT.key('Shift')) PlayerSpeed = 75;
else if (INPUT.key('Control')) PlayerSpeed = 250;
else PlayerSpeed = 150;

if (INPUT.key('ArrowRight') || INPUT.key('d')) self.Xmove(PlayerSpeed * dt, 0);
if (INPUT.key('ArrowLeft') || INPUT.key('a')) self.Xmove(-PlayerSpeed * dt, 0);
if (INPUT.key('ArrowUp') || INPUT.key('w')) self.Ymove(PlayerSpeed * dt, 0);
if (INPUT.key('ArrowDown') || INPUT.key('s')) self.Ymove(-PlayerSpeed * dt, 0);

if (INPUT.key('Space') && self.getPrivate("cooldown", 0) <= 0) {
  self.addObjectById("bled", { x: self.x, y: self.y });
  self.setPrivate("cooldown", 0.1);
}
self.setPrivate("cooldown", self.getPrivate("cooldown", 0) - dt);

// --- 無敵処理 ---
const muteki = self.getPrivate("muteki", 0);
if (self.touchesTag("enemy") && muteki <= 0) {
  self.setPrivate("muteki", 2.0);
  self.setPrivate("blinkTimer", 0);
}

if (muteki > 0) {
  const nextMuteki = muteki - dt;
  self.setPrivate("muteki", nextMuteki);

  const blink = self.getPrivate("blinkTimer", 0) + dt;
  self.setPrivate("blinkTimer", blink);

  const interval = 0.08;
  const phase = Math.floor(blink / interval);
  self.hidden = (phase % 2 === 0) ? false : true;

  if (nextMuteki <= 0) {
    self.hidden = false;
    self.setPrivate("muteki", 0);
    self.setPrivate("blinkTimer", 0);
  }
} else {
  self.hidden = false;
}

